{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to compute the net stage 1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Perseveration",
      "description": "Adds a constant bonus to the stage 1 action chosen on the previous trial to model choice stickiness.",
      "params": [
        {
          "name": "pers1",
          "bounds": [0, 5]
        }
      ],
      "evidence": "pers_bonus_1 = np.zeros(2)\nif last_action_1 != -1:\n    pers_bonus_1[last_action_1] = pers1\nexp_q1 = np.exp(beta * q_stage1_net + pers_bonus_1)",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_perseveration",
      "title": "Stage 2 Perseveration",
      "description": "Adds a state-specific constant bonus to the stage 2 action chosen the last time the current state was visited.",
      "params": [
        {
          "name": "pers2",
          "bounds": [0, 5]
        }
      ],
      "evidence": "pers_bonus_2 = np.zeros(2)\nif last_action_2[state_idx] != -1:\n    pers_bonus_2[last_action_2[state_idx]] = pers2\nexp_q2 = np.exp(beta * q_stage2_mf[state_idx] + pers_bonus_2)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free value using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Decays the model-free values of all unchosen stage 2 actions (both in the visited and unvisited states) towards 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_2 = 1 - action_2[trial]\nq_stage2_mf[state_idx, unchosen_action_2] += decay * (0.5 - q_stage2_mf[state_idx, unchosen_action_2])\nunvisited_state = 1 - state_idx\nq_stage2_mf[unvisited_state, 0] += decay * (0.5 - q_stage2_mf[unvisited_state, 0])\nq_stage2_mf[unvisited_state, 1] += decay * (0.5 - q_stage2_mf[unvisited_state, 1])",
      "expressible_in_slots": true
    }
  ]
}
